export const content={engine:{title:'Dentro del motor: de la combustión al giro.',intro:'Sigue la cadena: gases → pistón → biela → cigüeñal. Abre el corte, gira la cámara y toca cada pieza.',params:[['Ritmo didáctico',.1,1,.25,.05,'ciclos/s'],['Longitud de biela',1.6,1.95,1.85,.05,'u']],limits:'Cinemática ideal de un cilindro de gasolina, distribución sin adelantos. r = 0,55 unidades; carrera = 1,10. El gas coloreado identifica la etapa: no calcula presión, combustión ni torque. El ciclo de cuatro tiempos dura 720°. La reproducción es deliberadamente lenta.',phases:['Admisión','Compresión','Expansión','Escape'],moments:[['Entra la mezcla','El pistón baja y la válvula de admisión abre. El aumento de volumen permite que entre carga fresca.'],['Se comprime la carga','El pistón sube con ambas válvulas cerradas. Disminuye el volumen disponible sobre su corona.'],['La presión entrega trabajo','Cerca del punto muerto superior se enciende la mezcla. Durante la expansión, el gas empuja el pistón y la biela transmite fuerza al cigüeñal.'],['Salen los gases','El pistón sube con el escape abierto. Expulsa los gases y deja el cilindro preparado para otro ciclo.']],parts:[['piston','Pistón','Su corona recibe el empuje del gas; los segmentos ayudan a sellar la cámara. Solo se desplaza arriba y abajo dentro del cilindro.','Conecta con la biela mediante el bulón.'],['rod','Biela','La biela mantiene una distancia fija entre el bulón del pistón y el muñón de la manivela. Oscila mientras transmite fuerza.','Sus dos articulaciones convierten traslación y giro.'],['crank','Cigüeñal','El muñón está separado del eje una distancia r. Esa excentricidad transforma el recorrido del pistón en rotación.','Una vuelta produce dos carreras; un ciclo necesita dos vueltas.'],['intake','Admisión','La válvula de admisión abre en la bajada de admisión. Su muelle la mantiene cerrada en las otras etapas.','Paso de carga fresca hacia la cámara.'],['exhaust','Escape','Abre durante la subida de escape para dejar salir gases. Aquí su sincronización es idealizada.','Salida de gases después de la expansión.'],['spark','Bujía','Inicia la combustión con una chispa cerca del final de compresión. No empuja directamente el pistón.','La energía química de la carga produce el aumento de presión.'],['liner','Cilindro','Guía al pistón y delimita la cámara. El corte retira parte de la pared para que puedas ver el mecanismo.','Las aletas representan disipación de calor.'],['head','Culata','Cierra la parte superior y aloja válvulas y bujía. Los pernos la sujetan al bloque.','En el despiece se levanta junto a la distribución.'],['flywheel','Volante','Su inercia ayuda a suavizar la variación de velocidad entre carreras. En esta animación el ritmo se prescribe.','Almacena y devuelve energía cinética.'],['bearing','Cojinetes','Sostienen el eje y permiten su rotación con baja fricción.','Transmiten las reacciones a la bancada.']]},hydraulic:{title:'Dos pistones. Un mismo incremento de presión.',intro:'El pistón pequeño desplaza aceite hacia el grande. Mira cuánto sube la carga y por qué ganar fuerza cuesta recorrido.',params:[['Fuerza de entrada',10,100,20,5,'N'],['Relación de áreas A₂/A₁',1,8,4,.5,'×']],limits:'Prensa ideal de fluido incompresible. A₁ = 2 cm², sin fricción ni diferencia hidrostática significativa; p = F₁/A₁. Carrera máxima de entrada: 36 mm. El movimiento lento de ida y vuelta es prescrito, no calculado a partir de la carga. Marcadores de aceite ilustrativos. Despiece sin circulación.',phases:['Empujar','Máximo recorrido','Regresar'],parts:[['input','Pistón de entrada','Al bajar, reduce el volumen de aceite de su cámara. La fuerza aplicada genera un incremento de presión.','p = F₁/A₁. El área de entrada permanece fija.'],['output','Pistón de salida','Recibe la misma presión sobre un área mayor. Por eso puede ejercer más fuerza, pero sube menos distancia.','F₂ = F₁(A₂/A₁); x₂ = x₁(A₁/A₂).'],['pipe','Conducto','Conecta ambas cámaras. El volumen que sale de una debe entrar en la otra, si no hay compresión ni fugas.','A₁x₁ = A₂x₂.'],['fluid','Aceite','Transmite el incremento de presión y transporta energía. Su volumen total se conserva en este modelo.','La prensa no multiplica el trabajo: F₁x₁ = F₂x₂.'],['sleeve1','Cilindro pequeño','Guía y sella el pistón de entrada. Los tirantes sujetan las tapas.','El corte permite ver el aceite y el sello.'],['sleeve2','Cilindro grande','Su diámetro cambia al variar la relación de áreas: el radio crece como √(A₂/A₁).','El tamaño dibujado coincide con la relación elegida.'],['gauge','Manómetro','La aguja muestra la presión manométrica del modelo. Aumentar el área de salida no cambia p si F₁ y A₁ no cambian.','Escala ilustrada: 0–5 bar.'],['base','Bancada','Mantiene alineados los cilindros y soporta las reacciones.','Una máquina necesita estructura además del circuito.']]},motor:{title:'Tres corrientes crean un campo que gira.',intro:'Descubre las bobinas, el rotor de jaula y el eje. La flecha verde representa el campo; la marca del rotor permite comparar sus velocidades.',params:[['Frecuencia eléctrica',10,80,50,1,'Hz'],['Deslizamiento',0,15,4,.5,'%']],limits:'Motor equivalente de dos polos y alimentación trifásica equilibrada. Giro y corrientes ralentizados 100 veces. Deslizamiento impuesto: no calcula arranque, corriente inducida ni torque. Las seis bobinas son una distribución didáctica, no un plano de devanado. La flecha verde es una representación del campo, no una pieza. Con s = 0 no habría torque inducido sostenido en este modelo ideal.',phases:[],parts:[['stator','Estator y bobinas','Tres corrientes desfasadas 120° alimentan devanados distribuidos. Su combinación crea un campo magnético giratorio.','Los colores distinguen fases; el brillo sigue la corriente positiva de cada lado de bobina.'],['rotor','Rotor de jaula','Las barras conductoras están cortocircuitadas por anillos en sus extremos. La diferencia de velocidad respecto al campo permite inducir corriente.','n = ns(1 − s). La marca verde se mueve con el rotor.'],['field','Campo giratorio','La flecha verde representa la dirección del campo resultante. Es una guía visual superpuesta, no un imán físico girando.','Con dos polos: ns = 60 f. A 50 Hz, ns = 3 000 rpm.'],['bearings','Rodamientos','Centran el eje y reducen la fricción. El eje puede girar sin tocar el estator: queda un entrehierro.','El entrehierro permite movimiento relativo.'],['shield','Escudos','Cierran los extremos y soportan los rodamientos. Se muestran abiertos para observar el interior.','En el despiece se separan axialmente.'],['fan','Ventilador','Gira solidario con el eje y ayuda a mover aire para refrigerar el motor.','No produce el giro: utiliza parte de su energía.'],['housing','Carcasa','Protege el estator, fija el motor a la bancada y disipa calor mediante aletas.','Cierra el corte para ver su envolvente exterior.'],['terminal','Caja de bornes','Permite conectar los devanados a la alimentación externa. Aquí se muestran seis terminales didácticos.','La conexión real depende del motor y su placa.']]}};

content.pneumatic={title:'El aire toma un camino. El pistón responde.',intro:'Compresor → regulador → válvula 5/2 → cilindro. Sigue los puntos de alimentación y los de escape; invierte la válvula sin cambiar de golpe la posición del pistón.',params:[['Presión regulada',1,8,4,.5,'bar'],['Diámetro del pistón',20,80,40,2,'mm']],limits:'Circuito ideal con alimentación regulada constante y escape a 0 bar manométricos. Vástago de diámetro D/2; carrera de 100 mm. F = pA, sin carga, fricción ni contrapresión. Movimiento prescrito con pausas en los extremos: no calcula caudal, llenado del depósito, compresibilidad transitoria ni aceleración. Diámetros dibujados esquemáticos. Los puntos indican rutas y sentido, no moléculas ni velocidad real. El despiece oculta las conexiones y pausa el flujo.',phases:['Avance · 1→2 / 4→5','Fin de avance','Retorno · 1→4 / 2→3','Fin de retorno'],parts:[['compressor','Compresor y depósito','El compresor usa energía mecánica para aspirar aire y entregarlo al depósito a mayor presión. El depósito amortigua pulsaciones y almacena aire comprimido.','El giro del compresor es ilustrativo; aquí no se calcula el llenado.'],['regulator','Regulador','Ajusta la presión de alimentación del circuito. El manómetro muestra esta presión respecto a la atmósfera.','Más presión aumenta la fuerza ideal; no determina por sí sola la velocidad.'],['valve','Válvula 5/2','Tiene cinco vías y dos posiciones. 1 es alimentación; 2 y 4 van al cilindro; 3 y 5 son escapes separados.','Avance: 1→2 y 4→5. Retorno: 1→4 y 2→3.'],['spool','Corredera','Se desplaza dentro de la válvula para cambiar qué puertos se comunican. El corte muestra conexiones funcionales simplificadas.','Al invertir, el pistón conserva su posición y cambia el sentido del siguiente recorrido.'],['hoses','Conductos','El color azul identifica la ruta alimentada; el naranja identifica el aire que descarga. Los puntos avanzan en el sentido correspondiente.','Una cámara recibe aire mientras la otra lo expulsa.'],['cylinder','Cilindro de doble efecto','Las dos tapas cierran el cilindro y los tirantes las sujetan. Cada cámara tiene su propia conexión a la válvula.','Abre el corte para ver el pistón y el volumen de cada cámara.'],['piston','Pistón y vástago','El aire ejerce fuerza sobre una cara u otra. El vástago transmite el movimiento a una carga externa.','En retorno resta área: con d = D/2, Fret = 0,75 Fav.'],['chambers','Cámaras A y B','A es la cámara sin vástago; B es la cámara con vástago. La presión y la ruta cambian cuando conmuta la válvula.','En el extremo, la cámara sigue presurizada aunque ya no haya flujo ideal.'],['silencer','Escapes y silenciadores','El aire descargado sale al ambiente por 3 o 5, pasando por su silenciador. No vuelve al depósito.','Si el escape estuviera bloqueado, este modelo de movimiento ya no sería válido.']]};
content.plc={...content.pneumatic,title:'El pistón informa. El PLC decide.',intro:'Dos sensores magnéticos detectan los extremos del recorrido. Sigue sus señales hacia las entradas del PLC y observa cómo Q0.0 acciona la válvula 5/2.',params:[['Tiempo ideal de carrera',1,5,2,.1,'s'],['Espera en cada extremo',0,3,.6,.1,'s']],phases:[],limits:'PLC didáctico con scan de 20 ms: actualiza posición, lee entradas, ejecuta secuencia y escribe Q0.0. I0.0 detecta retraído; I0.1, extendido. Válvula monoestable: Q=1 avanza, Q=0 retorna por muelle. Presión fija 4 bar, D=40 mm, d=20 mm. Movimiento a velocidad prescrita; no simula dinámica del aire ni controla hardware. Pausar detiene el tiempo de la simulación, no representa una parada neumática segura. Un fallo desactiva Q y el cilindro retorna; no queda inmóvil.',parts:[['sensors','Sensores de posición','Dos sensores magnéticos montados sobre la camisa detectan el pistón al llegar a cada extremo. No necesitan tocarlo.','S0 → I0.0: retraído. S1 → I0.1: extendido.'],['plc','PLC y módulos I/O','En cada scan el PLC lee entradas, evalúa el estado de la secuencia y actualiza la salida. Los LEDs reproducen esas mismas variables.','La salida Q0.0 alimenta la bobina Y1 de la válvula.'],['wiring','Señales y cableado','Los cables violetas transportan las señales de los sensores; el cable de salida lleva la orden a la bobina. Se iluminan cuando la señal es verdadera.','La información eléctrica conmuta la válvula; el aire aporta la fuerza.'],...content.pneumatic.parts.filter(p=>!['spool'].includes(p[0]))]};
content.dual={...content.plc,title:'Dos cilindros. Una secuencia coordinada.',intro:'A+ → B+ → B− → A−. Cuatro sensores confirman cada movimiento; dos válvulas 5/2 convierten las órdenes del PLC en avance y retorno.',params:[['Tiempo ideal de carrera A',1,5,2,.1,'s'],['Tiempo ideal de carrera B',1,5,2,.1,'s']],limits:'Scan didáctico de 20 ms; carreras de 100 mm, velocidad prescrita y presión regulada fija de 4 bar. A: a0=I0.0, a1=I0.1, YA=Q0.0. B: b0=I0.2, b1=I0.3, YB=Q0.1. Una válvula monoestable por cilindro: salida 1 extiende, salida 0 retorna por muelle. En fallo ambas salidas caen y ambos cilindros retornan sin garantizar el orden normal. Pausar congela el tiempo didáctico; no es una parada neumática segura. No simula dinámica del aire ni controla hardware.',parts:[['A_sensors','Sensores a0 y a1','a0 confirma A retraído; a1 confirma A extendido y permite empezar B+.','I0.0 / I0.1'],['B_sensors','Sensores b0 y b1','b1 permite iniciar B−; b0 confirma su retorno antes de permitir A−.','I0.2 / I0.3'],['A_cylinder','Cilindro A','Avanza primero y permanece extendido durante los dos movimientos de B.','Q0.0 = 1 en A+, B+ y B−.'],['B_cylinder','Cilindro B','Avanza después de a1; retorna antes de que A pueda volver.','Q0.1 = 1 solo en B+.'],['A_valve','Válvula YA / Q0.0','Válvula 5/2 monoestable del cilindro A. Al desenergizar YA, retorna A.','1→2 / 4→5 al avanzar; 1→4 / 2→3 al retornar.'],['B_valve','Válvula YB / Q0.1','Una segunda válvula permite controlar B sin cambiar la orden de A.','Mismas cinco vías; circuito independiente aguas abajo.'],['plc','PLC: cuatro entradas, dos salidas','La memoria de etapa coordina los movimientos. Los LEDs muestran las variables que ejecuta el ladder.','Los sensores confirman; las salidas ordenan.'],['wiring','Cableado de señales','Cuatro cables de sensores y dos órdenes a las bobinas. Cada cable se ilumina con su señal.','La electricidad lleva información; el aire mueve los pistones.'],['A_compressor','Compresor común','El depósito y el regulador alimentan ambos ramales.','Alimentación ideal constante de 4 bar.'],['manifold','Alimentación compartida','Un colector conecta la salida regulada con la alimentación de ambas válvulas.','Los escapes van a la atmósfera, no al colector.']]};

content.dual.parts.splice(4,0,['A_piston','Pistón A','Se mantiene al final durante B+ y B− porque YA sigue energizada.','A− solo comienza después de b0.'],['B_piston','Pistón B','La posición de B activa b0 o b1 y determina la siguiente etapa.','Los puntos de aire muestran alimentación y escape.']);

content.dual.parts.unshift(['operator','Pupitre: marcha, paro y modo','Marcha habilita RUN. Paro o cambio de modo quita ambas salidas y hace retornar los cilindros. El selector separa automático de órdenes manuales.','Los botones operativos están encima del ladder. Marcha automática requiere a0 y b0; manual permite ordenar A y B por separado.']);

content.dual.intro='A+ → B+ → B− → A− con espera TON en cada extremo. El PLC cuenta cinco ciclos completos y termina el lote en origen. Ajusta las esperas con RUN=0 y pulsa Marcha.';
